"use client";

import { useState, useMemo } from "react";
import {
  MapPin,
  Plus,
  Home,
  Briefcase,
  MoreVertical,
  Check,
  X,
  Trash2,
  Phone,
  Star,
  Edit2,
} from "lucide-react";

// --- Types ---
type AddressType = "Home" | "Work" | "Other";

interface Address {
  id: string;
  name: string;
  phone: string;
  altPhone?: string;
  pincode: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  district: string;
  state: string;
  type: AddressType;
  isDefault: boolean;
}

// (Note: indianStatesAndDistricts remains unchanged, omitted for brevity)
const indianStatesAndDistricts: Record<string, string[]> = {
  /* ... your data ... */
};

const initialAddresses: Address[] = [
  {
    id: "1",
    name: "Ajmal",
    phone: "7558969093",
    pincode: "676552",
    addressLine1: "Flat 4B, Skyline Apartments",
    addressLine2: "Puthanathani Road",
    city: "Puthanathani",
    district: "Malappuram",
    state: "Kerala",
    type: "Home",
    isDefault: true,
  },
];

export default function AddressPage() {
  const [addresses, setAddresses] = useState<Address[]>(initialAddresses);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAddress, setEditingAddress] = useState<Address | null>(null);

  const handleDelete = (id: string) => {
    if (confirm("Delete this address?")) {
      setAddresses(addresses.filter((addr) => addr.id !== id));
    }
  };

  const handleSetDefault = (id: string) => {
    setAddresses(
      addresses.map((addr) => ({ ...addr, isDefault: addr.id === id }))
    );
  };

  const handleSaveAddress = (addressData: Address) => {
    let updated = [...addresses];
    if (addressData.isDefault)
      updated = updated.map((a) => ({ ...a, isDefault: false }));
    const idx = updated.findIndex((a) => a.id === addressData.id);
    idx >= 0 ? (updated[idx] = addressData) : updated.push(addressData);
    setAddresses(updated);
    setIsModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors">
      <main className="max-w-7xl mx-auto px-4 py-12 lg:pt-24">
        {/* Header Section */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-10 gap-6">
          <div className="space-y-2">
            <h1 className="text-3xl font-black uppercase tracking-tighter">
              My Addresses
            </h1>
            <p className="text-foreground-muted max-w-md">
              Manage delivery locations for a faster checkout experience.
            </p>
          </div>
          <button
            onClick={() => {
              setEditingAddress(null);
              setIsModalOpen(true);
            }}
            className="flex items-center gap-2 bg-brand text-brand-foreground px-8 py-3.5 rounded-4xl font-bold shadow-lg shadow-brand/20 transition-all hover:opacity-90 active:scale-95"
          >
            <Plus size={20} /> Add New Address
          </button>
        </div>

        {/* Address Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Add Shortcut Card */}
          <button
            onClick={() => {
              setEditingAddress(null);
              setIsModalOpen(true);
            }}
            className="hidden lg:flex flex-col items-center justify-center border-2 border-dashed border-border rounded-4xl text-foreground-subtle hover:border-brand hover:text-brand hover:bg-background-muted transition-all group min-h-[300px]"
          >
            <div className="w-14 h-14 rounded-full bg-background-muted flex items-center justify-center mb-4 group-hover:scale-110 group-hover:bg-brand group-hover:text-brand-foreground transition-all">
              <Plus size={28} />
            </div>
            <span className="font-bold uppercase text-xs tracking-widest">
              Add New Address
            </span>
          </button>

          {addresses.map((addr) => (
            <AddressCard
              key={addr.id}
              address={addr}
              onDelete={handleDelete}
              onSetDefault={handleSetDefault}
              onEdit={(a: any) => {
                setEditingAddress(a);
                setIsModalOpen(true);
              }}
            />
          ))}
        </div>
      </main>

      {isModalOpen && (
        <AddressFormModal
          initialData={editingAddress}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSaveAddress}
        />
      )}
    </div>
  );
}

// --- Sub-Component: Address Card ---

const AddressCard = ({ address, onDelete, onSetDefault, onEdit }: any) => (
  <div
    className={`p-6 rounded-4xl border transition-all duration-300 flex flex-col min-h-[300px] bg-background-elevated
    ${
      address.isDefault
        ? "border-brand ring-1 ring-brand shadow-xl"
        : "border-border shadow-sm hover:border-foreground-subtle"
    }`}
  >
    <div className="flex justify-between items-start mb-6">
      <div className="flex gap-2">
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black bg-background-muted text-foreground-muted uppercase tracking-widest">
          {address.type === "Home" ? (
            <Home size={12} />
          ) : address.type === "Work" ? (
            <Briefcase size={12} />
          ) : (
            <MapPin size={12} />
          )}
          {address.type}
        </span>
        {address.isDefault && (
          <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-[10px] font-black bg-brand text-brand-foreground uppercase tracking-widest">
            <Star size={10} fill="currentColor" /> Default
          </span>
        )}
      </div>

      <div className="flex gap-1">
        <button
          onClick={() => onEdit(address)}
          className="p-2 hover:bg-background-muted rounded-full text-foreground-subtle hover:text-foreground transition-colors"
        >
          <Edit2 size={16} />
        </button>
        <button
          onClick={() => onDelete(address.id)}
          className="p-2 hover:bg-destructive/10 rounded-full text-foreground-subtle hover:text-destructive transition-colors"
        >
          <Trash2 size={16} />
        </button>
      </div>
    </div>

    <div className="grow space-y-1">
      <h3 className="font-black text-lg">{address.name}</h3>
      <p className="text-foreground-muted text-sm line-clamp-1">
        {address.addressLine1}
      </p>
      <p className="text-foreground-muted text-sm line-clamp-1">
        {address.addressLine2}
      </p>
      <p className="text-foreground font-bold text-sm mt-2">
        {address.city}, {address.district}
      </p>
      <p className="text-foreground-subtle text-sm">
        {address.state} -{" "}
        <span className="text-foreground font-black tracking-widest">
          {address.pincode}
        </span>
      </p>

      <div className="mt-4 flex items-center gap-2 text-sm font-bold text-foreground bg-background-muted w-fit px-3 py-1.5 rounded-xl border border-border">
        <Phone size={14} className="text-brand" />
        <span>+91 {address.phone}</span>
      </div>
    </div>

    {!address.isDefault && (
      <div className="pt-4 mt-6 border-t border-border">
        <button
          onClick={() => onSetDefault(address.id)}
          className="text-[10px] font-black text-foreground-subtle hover:text-brand uppercase tracking-widest transition-colors"
        >
          Set as Default
        </button>
      </div>
    )}
  </div>
);

// --- Sub-Component: Address Form Modal ---

const AddressFormModal = ({ initialData, onClose, onSave }: any) => {
  const [formData, setFormData] = useState<Partial<Address>>(
    initialData || { type: "Home", isDefault: false }
  );

  const districts = useMemo(
    () =>
      formData.state ? indianStatesAndDistricts[formData.state] || [] : [],
    [formData.state]
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      id: initialData?.id || Date.now().toString(),
      ...formData,
    } as Address);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-background/60 backdrop-blur-md"
        onClick={onClose}
      />

      <div className="relative bg-background-elevated w-full max-w-2xl rounded-4xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden border border-border animate-in zoom-in-95 duration-200">
        {/* Modal Header */}
        <div className="px-8 py-6 border-b border-border flex justify-between items-center bg-background-elevated sticky top-0 z-10">
          <h2 className="text-xl font-black uppercase tracking-tighter">
            {initialData ? "Edit Address" : "New Address"}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-background-muted rounded-full transition-colors"
          >
            <X size={24} />
          </button>
        </div>

        <div className="p-8 overflow-y-auto no-scrollbar">
          <form id="address-form" onSubmit={handleSubmit} className="space-y-6">
            {/* Row 1: Identity */}
            <Input
              label="Full Name"
              placeholder="e.g. Ajmal"
              value={formData.name || ""}
              onChange={(v:string) => setFormData({ ...formData, name: v })}
            />

            {/* Row 2: Contact Info (Optimized Grid) */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Input
                label="Primary Phone"
                placeholder="10-digit number"
                value={formData.phone || ""}
                prefix="+91"
                onChange={(v:string) => setFormData({ ...formData, phone: v })}
              />
              <Input
                label="Alt Phone (Optional)"
                placeholder="Secondary number"
                value={formData.altPhone || ""}
                prefix="+91"
                onChange={(v:string) => setFormData({ ...formData, altPhone: v })}
              />
            </div>

            {/* Row 3: Location Basics */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Input
                label="Pincode"
                placeholder="e.g. 676552"
                value={formData.pincode || ""}
                onChange={(v:string) => setFormData({ ...formData, pincode: v })}
              />
              <div className="space-y-1.5">
                <label className="text-[10px] font-black uppercase tracking-widest text-foreground-subtle ml-1">
                  State
                </label>
                <select
                  className="w-full bg-background border border-border rounded-2xl px-4 py-3 text-sm font-bold outline-none focus:border-brand appearance-none"
                  value={formData.state || ""}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      state: e.target.value,
                      district: "",
                    })
                  }
                >
                  <option value="">Select State</option>
                  {Object.keys(indianStatesAndDistricts).map((s) => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Row 4: Detailed Address */}
            <div className="space-y-4">
              <Input
                label="Flat, House no., Building"
                placeholder="e.g. Flat 4B, Skyline Apartments"
                value={formData.addressLine1 || ""}
                onChange={(v:string) => setFormData({ ...formData, addressLine1: v })}
              />
              <Input
                label="Area, Street, Locality"
                placeholder="e.g. Puthanathani Road"
                value={formData.addressLine2 || ""}
                onChange={(v:string) => setFormData({ ...formData, addressLine2: v })}
              />
            </div>

            {/* Row 5: Type & Default Toggle */}
            <div className="flex flex-col md:flex-row justify-between md:items-center gap-6 pt-4">
              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-foreground-subtle ml-1">
                  Address Type
                </label>
                <div className="flex gap-2">
                  {(["Home", "Work", "Other"] as const).map((t) => (
                    <button
                      key={t}
                      type="button"
                      onClick={() => setFormData({ ...formData, type: t })}
                      className={`px-6 py-2 rounded-full text-[10px] font-black border transition-all uppercase tracking-widest
                      ${
                        formData.type === t
                          ? "bg-brand text-brand-foreground border-brand shadow-md"
                          : "bg-background text-foreground-muted border-border"
                      }`}
                    >
                      {" "}
                      {t}{" "}
                    </button>
                  ))}
                </div>
              </div>

              <label className="flex items-center gap-3 cursor-pointer group bg-background-muted p-4 rounded-2xl border border-border/50">
                <div
                  className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${
                    formData.isDefault
                      ? "bg-brand border-brand"
                      : "border-border bg-background"
                  }`}
                >
                  {formData.isDefault && (
                    <Check size={14} className="text-brand-foreground" />
                  )}
                </div>
                <input
                  type="checkbox"
                  className="hidden"
                  checked={formData.isDefault}
                  onChange={(e) =>
                    setFormData({ ...formData, isDefault: e.target.checked })
                  }
                />
                <span className="text-xs font-bold text-foreground-muted group-hover:text-foreground">
                  Set as default address
                </span>
              </label>
            </div>
          </form>
        </div>

        {/* Modal Footer */}
        <div className="px-8 py-5 border-t border-border bg-background-muted flex gap-4">
          <button
            onClick={onClose}
            className="flex-1 px-6 py-3.5 rounded-4xl font-bold text-foreground-muted hover:bg-background transition-colors uppercase text-[10px] tracking-widest"
          >
            Cancel
          </button>
          <button
            type="submit"
            form="address-form"
            className="flex-1 px-6 py-3.5 rounded-4xl bg-brand text-brand-foreground font-black hover:opacity-90 transition-all shadow-lg shadow-brand/10 uppercase text-[10px] tracking-widest"
          >
            Save Address
          </button>
        </div>
      </div>
    </div>
  );
};

const Input = ({ label, value, onChange, prefix }: any) => (
  <div className="space-y-1.5 w-full">
    <label className="text-[10px] font-black uppercase tracking-widest text-foreground-subtle ml-1">
      {label}
    </label>
    <div className="relative">
      {prefix && (
        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground-subtle text-sm font-bold">
          {prefix}
        </span>
      )}
      <input
        className={`w-full bg-background border border-border rounded-2xl py-3 text-sm font-bold outline-none focus:border-brand transition-all ${
          prefix ? "pl-12" : "px-4"
        }`}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
    </div>
  </div>
);
